def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # Maps id to (side, price, arrival_time, index_in_book)
    arrival_time = 0

    for order in orders:
        arrival_time += 1
        order_type = order[0]
        order_id = order[1]

        if order_type == 'cancel':
            if order_id in order_map:
                side, price, arr_time, book_index = order_map[order_id]
                if side == 'buy':
                    if book_index < len(buy_book) and buy_book[book_index][2] == order_id:
                        # Mark as cancelled by setting qty to 0
                        buy_book[book_index] = (buy_book[book_index][0], buy_book[book_index][1], buy_book[book_index][2], 0)
                else:
                    if book_index < len(sell_book) and sell_book[book_index][2] == order_id:
                        sell_book[book_index] = (sell_book[book_index][0], sell_book[book_index][1], sell_book[book_index][2], 0)
                del order_map[order_id]

        else:
            side = order[2]

            if order_type == 'market':
                qty = order[3]
                price = None
            else:
                price = order[3]
                qty = order[4]

            # Match incoming order
            if side == 'buy':
                # Match against sell book
                while qty > 0 and sell_book:
                    # Remove cancelled orders from front
                    while sell_book and sell_book[0][3] == 0:
                        sell_book.pop(0)

                    if not sell_book:
                        break

                    sell_price, sell_arr_time, sell_id, sell_qty = sell_book[0]

                    # Check if match is possible
                    if price is not None and sell_price > price:
                        break

                    # Execute trade
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    qty -= trade_qty
                    sell_book[0] = (sell_price, sell_arr_time, sell_id, sell_qty - trade_qty)

                    if sell_book[0][3] == 0:
                        sell_book.pop(0)

            else:  # side == 'sell'
                # Match against buy book
                while qty > 0 and buy_book:
                    # Remove cancelled orders from front
                    while buy_book and buy_book[0][3] == 0:
                        buy_book.pop(0)

                    if not buy_book:
                        break

                    buy_price, buy_arr_time, buy_id, buy_qty = buy_book[0]

                    # Check if match is possible
                    if price is not None and buy_price < price:
                        break

                    # Execute trade
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    qty -= trade_qty
                    buy_book[0] = (buy_price, buy_arr_time, buy_id, buy_qty - trade_qty)

                    if buy_book[0][3] == 0:
                        buy_book.pop(0)

            # Add to book if limit order with remaining qty
            if order_type == 'limit' and qty > 0:
                if side == 'buy':
                    # Insert maintaining price-time priority (highest price first, then earliest)
                    inserted = False
                    for i, (p, arr, bid, bqty) in enumerate(buy_book):
                        if p < price or (p == price and arr > arrival_time):
                            buy_book.insert(i, (price, arrival_time, order_id, qty))
                            inserted = True
                            break
                    if not inserted:
                        buy_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = ('buy', price, arrival_time, len(buy_book) - 1)
                else:  # sell
                    # Insert maintaining price-time priority (lowest price first, then earliest)
                    inserted = False
                    for i, (p, arr, sid, sqty) in enumerate(sell_book):
                        if p > price or (p == price and arr > arrival_time):
                            sell_book.insert(i, (price, arrival_time, order_id, qty))
                            inserted = True
                            break
                    if not inserted:
                        sell_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = ('sell', price, arrival_time, len(sell_book) - 1)

    return trades

